static boolean allNonDaemonThreadsFinished() {
    for (Thread t : Thread.getAllStackTraces().keySet()) {
        if (t != Thread.currentThread() && !t.isDaemon() && t.getState() != Thread.State.TERMINATED) return false;
    }
    return true;
}
