class BestEffortExecutor {
    private final ExecutorService pool;
    BestEffortExecutor(int threads) { pool = Executors.newFixedThreadPool(threads, r -> { Thread t = new Thread(r); t.setDaemon(true); return t; }); }
    void submitBestEffort(Runnable task) { pool.submit(task); }
    void shutdown() throws InterruptedException { pool.shutdown(); pool.awaitTermination(2, TimeUnit.SECONDS); }
}
