static boolean checkIfAliveAfter(Runnable task, boolean daemon, long checkAfterMs) throws InterruptedException {
    Thread t = new Thread(task);
    t.setDaemon(daemon);
    t.start();
    Thread.sleep(checkAfterMs);
    boolean alive = t.isAlive();
    t.interrupt(); // sprzatanie - zawsze przerwij po tescie
    t.join(500);
    return alive;
}
Runnable dlugie = () -> { try { Thread.sleep(2000); } catch (InterruptedException e) {} };
System.out.println("user thread po 200ms nadal zywy: "+checkIfAliveAfter(dlugie, false, 200)); // true - 'zablokowalby' JVM
System.out.println("daemon thread po 200ms nadal zywy: "+checkIfAliveAfter(dlugie, true, 200)); // true, ale NIE 'blokuje' JVM

